contracts/Factory.sol.content:
// contracts/GLDToken.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./Token.sol";
import "./Pools.sol";
import "./Staking.sol";


contract Factory {

    // token objects
    Token public gerdaCoin;
    Token public krendelCoin;
    Token public rtkCoin;
    Token public professionalCoin;

    // poll objects
    Pool public poolGerKre;  
    Pool public poolKreRtk;

    Staking public staking;

    struct user {
        string name;
    }

    mapping (address => user) public users;

    uint decimals = 12;


    constructor() {
        gerdaCoin = new Token("GerdaCoin", "GERDA", 100_000, 1 ether);
        krendelCoin = new Token("KrendelCoin", "KRENDEL", 150_000, 15e17);
        rtkCoin = new Token("RTKCoin", "RTK", 300_000, 3 ether);
        professionalCoin = new Token("Professional", "PROFI", 0, 6 ether);

        staking = new Staking(professionalCoin);   

        // создание пользователей
        address tom = 0x5B38Da6a701c568545dCfcB03FcB875f56beddC4;
        address ben = 0xAb8483F64d9C6d1EcF9b849Ae677dD3315835cb2;
        address rick = 0x78731D3Ca6b7E34aC0F824c42a7cC18A495cabaB;

        users[tom] = user("Tom");
        users[ben] = user("Ben");
        users[rick] = user("Rick");

        uint tokenAmount = 10000 * 10 ** 12;

        // перевод токенов
        gerdaCoin.transfer(tom, tokenAmount);
        krendelCoin.transfer(tom, tokenAmount);
        rtkCoin.transfer(tom, tokenAmount);

        gerdaCoin.transfer(ben, tokenAmount);
        krendelCoin.transfer(ben, tokenAmount);
        rtkCoin.transfer(ben, tokenAmount);

        // создание пулов
        poolGerKre = new Pool(
            "poolGerKre",
            0x5B38Da6a701c568545dCfcB03FcB875f56beddC4,
            gerdaCoin,
            krendelCoin,
            professionalCoin
        ); // владелец том
        poolKreRtk = new Pool(
            "poolKreRtk",
            0xAb8483F64d9C6d1EcF9b849Ae677dD3315835cb2,
            krendelCoin,
            rtkCoin,
            professionalCoin
        ); // владелец бен

        // перевод токенов в пулы

        // GERDA-KRENDEL: 1500 ETH : 1500 ETH
        gerdaCoin.transfer(address(poolGerKre), 1500 * 10 ** 12);
        krendelCoin.transfer(address(poolGerKre), 1000 * 10 ** 12);

        // KRENDEL-RTK: 3000 ETH : 3000 ETH
        krendelCoin.transfer(address(poolKreRtk), 2000 * 10 ** 12);
        rtkCoin.transfer(address(poolKreRtk), 1000 * 10 ** 12);
    }

}

contracts/Token.sol.content:
// contracts/GLDToken.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract Token is ERC20 {

    uint8 constant _decimals = 12;
    uint price;
    uint initialSupply;

    constructor(string memory _name, string memory _symbol, uint _initialSupply, uint _price) ERC20(_name, _symbol) {
        _mint(msg.sender, _initialSupply * 10 ** _decimals);
        price = _price;
        initialSupply = _initialSupply;
    }


    function decimals() public pure override returns (uint8) {
        return _decimals;
    }

    function getPrice() public view returns (uint) {
        return price;
    }

    function mint(address to, uint amount) public {
        _mint(to, amount);
    }

    function getPriceInBuyToken(uint _amount) public view returns(uint) {
        return _amount * getPrice();
    }

    // function buyToken()
    function buyToken(uint _amount) public payable {
        // посчитать количество того, сколько пользователь должен заплатить за токен
        uint amount = _amount * 10 ** decimals();
        uint price = getPriceInBuyToken(_amount);

        // проверить, есть ли такое количество токенов у пользователя
        require(msg.value >= price, unicode"У вас не достаточно ETH для покупки данного количества токенов");

        if (msg.value > price) {
            payable(msg.sender).transfer(msg.value - price); // переводим остаток обратно, при его наличии
        }

        _mint(msg.sender, amount); // минтим новые токены пользователю
    }

}

