// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;


import "./Token.sol";

contract Pool {

    address owner;
    string name;
    Token token1;
    Token token2;
    uint decimals = 12;
    Token public professionalCoin;

    constructor (string memory _name, address _owner, Token _token_first, Token _token_second, Token lpProfi) {
        name = _name;
        token1 = _token_first;
        token2 = _token_second;
        owner = _owner;
        professionalCoin = lpProfi;
    }


    function swap_token(address _swapToken, address _pool, uint _amount) public  {
        uint amount = _amount * 10 ** uint(decimals);

        // проверка на то есть ли такое кол-во токенов у пользователя
        require(
            Token(_swapToken).balanceOf(msg.sender) >= amount,
            unicode"вы не можете поменять больше токенов, чем у вас в ноличии"
        );

        // проверка на то есть ли такие токены в пуле
        require(
            _swapToken == address(token1) || _swapToken == address(token2),
            "invalid token"
        );

        uint balanceToken1 = Token(token1).balanceOf(_pool);
        uint balanceToken2 =  Token(token2).balanceOf(_pool);

        if (_swapToken == address(token1)) {
            uint tokensOut = 
            (amount * token1.getPrice() * balanceToken2)
                            / 
            (token2.getPrice() * balanceToken1);

            require(Token(token2).balanceOf(_pool) >= tokensOut, "the pool doesn't have enough tokens to exchange");

            Token(token1).transferFrom(msg.sender, _pool, amount); // от пользователя к пулу
            Token(token2).transfer(msg.sender, tokensOut); // от пула к пользователю 
        } else {
            uint tokensOut = 
            (amount * token2.getPrice() * balanceToken1)
                            / 
            (token1.getPrice() * balanceToken2);

            require(Token(token1).balanceOf(_pool) >= tokensOut, "the pool doesn't have enough tokens to exchange");

            Token(token2).transferFrom(msg.sender, _pool, amount);
            Token(token1).transfer(msg.sender, tokensOut);
        }
    }

    function getTokenBalance(Token _token) public view returns(uint) {
        return _token.balanceOf(msg.sender);
    }


    function liquidityUp(address _token, uint _amount) public {
        uint amount = _amount * 10 ** decimals;

        // проверка того существуют ли токены в пуле
        require(
            _token == address(token1) || _token == address(token2),
            "invalid token"
        );

        // создание объекта для удобства
        Token inputToken = Token(_token);

        // проверка того достаточно ли токенов у отправителя
        require(
            inputToken.balanceOf(msg.sender) >= amount,
            "not enough tokens"
        );

        // переводим токены от нас к пулу
        inputToken.transferFrom(msg.sender, address(this), amount);

        // получаем ценц токена
        uint tokenPrice;

        if (_token == address(token1)) {
            tokenPrice = token1.getPrice();
        } else {
            tokenPrice = token2.getPrice();
        }

        // cчитаем всё в соотношении с ценой
        // стоимость вклада = amount * priceToken
        // LP к выдаче = стоимость вклада / priceLP
        uint lpTokensOut = (amount * tokenPrice) / professionalCoin.getPrice();

        professionalCoin.mint(msg.sender, lpTokensOut);
    }

}

contracts/Staking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;


import "./Token.sol";

contract Staking {

    Token public profi;

    mapping(address => uint) public stakes;
    mapping(address => uint) public lastRewardTime;

    uint public totalStaked;
    uint PRECISION = 1e18;

    uint constant public decimals = 10 ** 12;
    uint constant REWARD_PER_SECOND = 13 * decimals;

    constructor(Token professionalCoin) {
        profi = professionalCoin;
    }

    // положить на стэйк
    function stake(uint _amount) public {

        uint amount = _amount * 10 ** profi.decimals();

        require(_amount > 0, "amount is zero");
        require(
            profi.balanceOf(msg.sender) >= amount,
            unicode"Недастаточно LP(profi) токенов на балансе"
        );

        if (stakes[msg.sender] > 0) {
            claimReward();
        } else {
            lastRewardTime[msg.sender] = block.timestamp;
        }

        stakes[msg.sender] += amount;
        totalStaked += amount;               

        profi.transferFrom(msg.sender, address(this), amount);

    }

    // формула для подсчета
    function calculateReward() public view returns(uint) {

        // для того чтобы не писать каждый раз stakes[msg.sender]
        uint stakedAmount = stakes[msg.sender];

        // проверка на то не является ли его стэйкинг пустым
        if (stakedAmount == 0 || totalStaked == 0) {
            return 0;
        }

        // всё прошедшее время с последнего момента
        uint timeElapsed = block.timestamp - lastRewardTime[msg.sender];

        // проверка на то не является ли его стэйкинг пустым
        if (timeElapsed == 0) {
            return 0;
        }

        // countLP / allLP + 1
        uint stakeMultiplier = PRECISION + (stakedAmount * PRECISION) / totalStaked;

        // ((timeElapsed / 30 days) * 0.05) + 1
        uint timeMultiplier = PRECISION + ((timeElapsed * 5 * PRECISION) / (100 * 30 days));

        // окончательня награда
        uint reward = (
            stakedAmount *
            timeElapsed *
            REWARD_PER_SECOND *
            stakeMultiplier *
            timeMultiplier
        ) / (PRECISION * PRECISION * decimals);

        return reward;
    }

    // забрать со стэйка
    function claimReward() public {
        uint reward = calculateReward();
        require(reward > 0, "No reward available");

        lastRewardTime[msg.sender] = block.timestamp;

        profi.mint(msg.sender, reward);
    }
}

